$(function(){$("a.page-scroll").bind("click",function(t){var a=$(this),n=$(".navbar-fixed-top"),s=$(this.hash);if(t.preventDefault(),!s.length)return;if(window.innerWidth<768){var c=n.find(".navbar-collapse");c.one("hidden.bs.collapse",function(){$("html, body").stop().animate({scrollTop:s.offset().top-n.outerHeight()-24},1500,"easeInOutExpo")}),c.collapse("hide")}else{var h=n.outerHeight();n.hasClass("navbar-shrink")||(h-=20),$("html, body").stop().animate({scrollTop:s.offset().top-h-24},1500,"easeInOutExpo")}})}),$("body").scrollspy({target:".navbar-fixed-top"}),$(".navbar-collapse ul li a").click(function(){$(".navbar-toggle:visible").click()});